mapper.select:
select applicant_dept_id as deptId,
applicant_dept_name as deptName,
count(id) as applyNum,
sum(if(`status` = 'PASS',1,0)) AS passNum
from flow_form_data ff
where ff.deleted = 0

    and ff.business_type = #{param.businessType}


    and ff.applicant_dept_id = #{param.deptId}


    and ff.status = #{param.status}


    and ff.apply_time >= #{param.startTime}


    and ff.apply_time < #{param.endTime}

group by applicant_dept_id

select applicant_dept_id,
applicant_dept_name as deptName,
applicant_id,applicant_name as applicantName,
status,
apply_time,
apply_done_time
from flow_form_data ff
where ff.deleted = 0

    and ff.business_type = #{param.businessType}


    and ff.applicant_dept_id = #{param.deptId}


    and ff.status = #{param.status}


    and ff.apply_time >= #{param.startTime}


    and ff.apply_time < #{param.endTime}

select ff.json_form ->> '$.sealId' as sealId,count(id) as applyNum,count(DISTINCT ff.applicant_id) as applicantNum
from flow_form_data ff
where ff.deleted = 0 and ff.status = 'PASS'

    and ff.business_type = #{param.businessType}


    and ff.apply_time >= #{param.startTime}


    and ff.apply_time < #{param.endTime}

GROUP BY ff.json_form ->> '$.sealId'

select ff.json_form ->> '$.sealName' as sealName,ff.applicant_id,ff.applicant_name,ff.`status`,ff.apply_time,ff.apply_done_time
from flow_form_data ff
where ff.deleted = 0 and ff.status = 'PASS'

    and ff.business_type = #{param.businessType}


    and ff.json_form ->> '$.sealName' like concat("%",#{param.name},"%")


    and ff.json_form ->> '$.sealId' = #{param.id}


    and ff.apply_time >= #{param.startTime}


    and ff.apply_time < #{param.endTime}

select ff.json_form ->> '$.fromUnit' as fromUnit, ff.json_form ->> '$.fileCode' as fileCode, ff.json_form ->> '$.timeLimit' as timeLimit, ff.applicant_id, ff.applicant_name, ff.apply_time, ff.apply_done_time from flow_form_data ff where ff.deleted = 0
and ff.business_type = #{param.businessType}
and ff.status = #{param.status}
and ff.apply_time >= #{param.startTime}
and ff.apply_time < #{param.endTime}
order by ff.apply_time desc

select ff.applicant_id, ff.applicant_name, ff.applicant_dept_id as deptId, ff.applicant_dept_name as deptName, ff.json_form ->> '$.workCategoryId' as workCategoryId, COUNT(id) as applyNum, sum(if(ff.`status` = 'PASS',1,0)) AS passNum from flow_form_data ff where ff.deleted = 0
and ff.business_type = #{param.businessType}
and ff.apply_time >= #{param.startTime}
and ff.apply_time < #{param.endTime}
GROUP BY ff.applicant_id,ff.json_form -> '$.workCategoryId'

select ff.applicant_dept_id as deptId,ff.applicant_dept_name as deptName,
ff.json_form ->> '$.focusWorkId' as focusWorkId,
COUNT(id) as applyNum,
sum(if(ff.json_form -> '$.status' = 'STOP',1,0)) AS stopNum,
sum(if(ff.json_form -> '$.status' = 'PROCESSING_DELAY',1,0)) as delayNum
from flow_form_data ff
where ff.deleted = 0

    and ff.business_type = #{param.businessType}


    and ff.status = #{param.status}


    and ff.apply_time >= #{param.startTime}


    and ff.apply_time < #{param.endTime}

GROUP BY ff.applicant_dept_id,ff.json_form -> '$.focusWorkId'

select  ff.business_type,
count(id) as applyNum
from flow_form_data ff
where ff.deleted = 0
  and ff.status = 'PASS'

    and ff.business_type in

        #{businessType}



    and ff.apply_time >= #{period.begin}


    and ff.apply_time < #{period.end}

group by ff.business_type
